#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>

using namespace std;

bool canJump(vector<int>& nums) {
    int furthest = 0;
    for (int i = 0; i < nums.size(); i++) {
        if (i > furthest) return false;
        furthest = max(furthest, i + nums[i]);
        if (furthest >= (int)nums.size() - 1) return true;
    }
    return furthest >= (int)nums.size() - 1;
}

int main() {
    string line; if (!getline(cin, line)) return 0;
    for (char &c : line) if (c == '[' || c == ']' || c == ',') c = ' ';
    stringstream ss(line);
    int val; vector<int> nums;
    while (ss >> val) nums.push_back(val);
    if (nums.empty()) return 0;
    cout << (canJump(nums) ? "true" : "false") << endl;
    return 0;
}

